// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    __InvMutHandleStub shareStub;

    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(uint256 amount, address from, address to, address caller) public {
        vm.assume(amount < type(uint256).max);
        vm.assume(caller != address(0) && from != address(0) && to != address(0));
        // recover the share stub deployed in setUp and drive it to return FALSE (call still succeeds)
        shareStub = __InvMutHandleStub(payable(address(c.share())));
        shareStub.setTransferFromResult(false);

        vm.prank(caller);
        (bool callOk, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.transferFrom.selector, from, to, amount)
        );
        // the call completes without reverting in both versions; decode the returned boolean
        assertTrue(callOk && !abi.decode(ret, (bool)), "transferFrom must return the token's returned boolean (false), not the success flag");
    }
}

contract __InvMutHandleStub {
    bool public transferFromResult = true;

    function setTransferFromResult(bool v) external { transferFromResult = v; }

    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external view returns (bool) { return transferFromResult; }
    function checkTransferRestriction(address, address, uint256) external pure returns (bool) { return true; }
    function permit(address, address, uint256, uint256, uint8, bytes32, bytes32) external pure {}
    function PERMIT_TYPEHASH() external pure returns (bytes32) { return bytes32(0); }
    function DOMAIN_SEPARATOR() external view returns (bytes32) { return bytes32(0); }
    receive() external payable {}
    fallback() external payable {}
}
